x = abs(int(input()))
csc = []

for i in range(0, 45000):
    csc.append(i * (i + 1) // 2)

def solve(csc, x):
    if x == 0:
        return 0
    for i in range(len(csc)):
        if csc[i] >= x:
            if (csc[i] - x) % 2 == 0:
                return i
            elif (csc[i + 1] - x) % 2 == 0:
                return i + 1
            else:
                return i + 2

print(solve(csc, x))

