def findN(sum):
    sum = abs(sum)
    i = 0
    num = 0
    while num < sum:
        i += 1
        num += i
    diff = num - sum
    if diff % 2 == 0:
        print(i)
    elif i % 2 == 0:
        print(i + 1)
    else:
        print(i + 2)


x = int(input())
findN(x)

def findN(sumNum):
    i = 0
    num = 0
    if sumNum < 0:
        sumNum = -sumNum
    while num < sumNum:
        i += 1
        num += i
    if num == sumNum:
        print(i)
    else:
        diff = num - sumNum
        if diff % 2 == 0:
            print(i)
        elif i % 2 == 0:
            print(i + 1)
        else:
            print(i + 2)


x = int(input())
findN(x)

